@triton.jit
def reflection_pad1d_small_kernel(
    in_ptr,
    out_ptr,
    B,
    W_in,
    pad_left,
    W_out,
    BLOCK_W: tl.constexpr,
):
    # lean launch-floor path for shapes that fit a single 48-program wave:
    # one masked block per (row, column tile), closed-form reflection without
    # the generic abs/%/where chain (the % is a multi-cycle emulation on
    # this backend). Dispatched only when the whole grid fits one wave, so
    # the per-program dispatch tax never stacks up.
    pid_b = tl.program_id(axis=0)
    pid_w = tl.program_id(axis=1)

    offs_w = pid_w * BLOCK_W + tl.arange(0, BLOCK_W)
    mask = (offs_w < W_out) & (pid_b < B)

    base_in = pid_b * W_in
    base_out = pid_b * W_out

    # closed-form reflection (pads < W_in guaranteed by the host): the two
    # boundary bands never wrap more than once, so no modulo is needed
    x = offs_w - pad_left
    neg = x < 0
    big = x >= W_in
    iw = tl.where(neg, -x, tl.where(big, 2 * W_in - 2 - x, x))

    vals = tl.load(in_ptr + base_in + iw, mask=mask, other=0)
    tl.store(out_ptr + base_out + offs_w, vals, mask=mask)


@triton.jit
def reflection_pad1d_wide_kernel(
    x_ptr,
    o_ptr,
    R,
    W,
    Wo,
    pl,
    BLOCK: tl.constexpr,
    FPAD: tl.constexpr,
    WIDE: tl.constexpr,
):
    # general path for very wide rows (W > 8192): per-row chunked interior
    # copy plus chunked mirror copies; correctness-first, off the hot path.
    pid = tl.program_id(0)
    G = tl.num_programs(0)
    prw = Wo - W - pl
    CB = (W + BLOCK - 1) // BLOCK
    CL = (pl + FPAD - 1) // FPAD
    CR = (prw + FPAD - 1) // FPAD
    offs_b = tl.arange(0, BLOCK)
    offs_f = tl.arange(0, FPAD)
    for r in range(pid, R, G):
        if WIDE:
            srow = r.to(tl.int64) * W
            drow = r.to(tl.int64) * Wo
        else:
            srow = r * W
            drow = r * Wo
        for c in range(0, CB):
            ob = c * BLOCK + offs_b
            m = ob < W
            tl.store(
                o_ptr + drow + pl + ob,
                tl.load(x_ptr + srow + ob, mask=m),
                mask=m,
            )
        for c in range(0, CL):
            ol = c * FPAD + offs_f
            ml = ol < pl
            sl = tl.where(ml, pl - ol, 0)
            tl.store(o_ptr + drow + ol, tl.load(x_ptr + srow + sl, mask=ml), mask=ml)
        for c in range(0, CR):
            orr = c * FPAD + offs_f
            mr = orr < prw
            sr = tl.where(mr, W - 2 - orr, 0)
            tl.store(
                o_ptr + drow + W + pl + orr,
                tl.load(x_ptr + srow + sr, mask=mr),
                mask=mr,
            )


def _next_pow2(n, cap):
    p = 1
    while p < n and p < cap:
        p *= 2
    return p


def _launch_reflection_pad1d(input: torch.Tensor, padding, out: torch.Tensor = None):
    if not isinstance(padding, (list, tuple)) or len(padding) != 2:
        raise ValueError(
            "padding must be a sequence of length 2: (pad_left, pad_right)"
        )
    pad_left, pad_right = int(padding[0]), int(padding[1])
    if pad_left < 0 or pad_right < 0:
        raise ValueError("padding values must be >= 0")
    if input.dim() < 1:
        raise ValueError("input must have at least 1 dimension")

    x = input.contiguous()
    W_in = int(x.shape[-1])
    if W_in <= 0:
        raise ValueError("last dimension (width) must be > 0")

    W_out = W_in + pad_left + pad_right
    leading_shape = x.shape[:-1]
    B = int(math.prod(leading_shape)) if len(leading_shape) > 0 else 1

    if out is None:
        out = torch.empty((*leading_shape, W_out), device=x.device, dtype=x.dtype)
    else:
        expected_shape = (*leading_shape, W_out)
        if tuple(out.shape) != expected_shape:
            raise ValueError(
                f"out tensor has shape {tuple(out.shape)}, expected {expected_shape}"
            )
        if out.dtype != x.dtype:
            raise ValueError(
                f"out dtype {out.dtype} does not match input dtype {x.dtype}"
            )
        if out.device != x.device:
            raise ValueError("out must be on the same device as input")
        out = out.contiguous()

    # Validate reflection padding constraints (only when there is padding)
    if pad_left > 0 or pad_right > 0:
        if W_in < 2:
            raise ValueError(
                "input width must be at least 2 for reflection padding when padding > 0"
            )
        if pad_left >= W_in or pad_right >= W_in:
            raise ValueError(
                "padding values must be less than the input width for reflection padding"
            )

    R = B
    PW = pad_left + pad_right
    # flat element offsets beyond 2^31 need the int64 address path
    wide = R * W_out >= 2**31

    def _launch():
        if W_in > 8192:
            # very wide rows: chunked general path
            FPAD = max(16, _next_pow2(max(pad_left, pad_right, 1), 1024))
            grid = (min(48, max(1, R)),)
            reflection_pad1d_wide_kernel[grid](
                x,
                out,
                R,
                W_in,
                W_out,
                pad_left,
                BLOCK=8192,
                FPAD=FPAD,
                WIDE=wide,
                num_warps=8,
            )
            return
        # single-wave shapes (<= 48 programs) take the lean per-row kernel:
        # its tiny prologue beats the row-group kernel's scalar setup chain on
        # launch-floor shapes (measured 3.2us vs 4.1us on the (3,33) shape)
        if W_out > 1:
            BLOCK_S = 1 << min(10, (W_out - 1).bit_length())
        else:
            BLOCK_S = 1
        nblk = (W_out + BLOCK_S - 1) // BLOCK_S
        if R * nblk <= 48:
            grid = (max(1, R), nblk)
            reflection_pad1d_small_kernel[grid](
                x,
                out,
                R,
                W_in,
                pad_left,
                W_out,
                BLOCK_W=BLOCK_S,
                num_warps=2,
            )
            return
        # rows per group: wide rows are bandwidth-bound (small groups),
        # narrow rows are latency-bound (large groups hide the ~450ns
        # per-op latency). Small R clamp: when fewer groups than programs
        # would result, prefer more programs with smaller groups.
        # U x BLOCK x 4B (fp32 register budget) is capped at ~128KB
        # (the reflection_pad2d shipped ceiling): U=8 only under 4096-wide
        # rows, U=4 above (measured: U=16 at 2048 regress 6-12%).
        if W_in >= 4096:
            U = 4
        elif W_in >= 2048:
            U = 8
        elif W_in >= 768 or W_in < 64:
            U = 8
        else:
            U = 20
        n_min = (R + 47) // 48
        if n_min <= 4:
            U_r = 4
        elif n_min <= 8:
            U_r = 8
        else:
            U_r = 20
        U = min(U, U_r)
        nw = 2 if U == 20 else 4
        # next power of two via bit_length: no python loop on the hot path
        BLOCK = 1 << min(13, (W_in - 1).bit_length())
        total = R * PW
        # pad gather block scaled to the mirror-lane total (16..1024)
        if total > 0:
            GB = 1 << min(10, max(4, (total - 1).bit_length()))
        else:
            GB = 16
        tail = R - (R // U) * U
        grid = (
            min(
                48,
                max(
                    1,
                    (R - tail) // U + tail + (total + GB - 1) // GB,
                ),
            ),
        )
        reflection_pad1d_rowseg_kernel[grid](
            x,
            out,
            R,
            W_in,
            W_out,
            pad_left,
            BLOCK=BLOCK,
            GBLOCK=GB,
            U=U,
            WIDE=wide,
            num_warps=nw,
        )

    # cold compiles hit the documented node-level toolchain flakiness
    # (P02 family): a fresh-compile subprocess can die before producing a
    # cache entry; retrying the launch re-enters compilation and succeeds
    # (atan2_/sinh/_pad_circular precedent). Zero cost on the warm path.
    for attempt in range(3):
        try:
            with torch_device_fn.device(x.device):
                _launch()
            break
        except Exception:
            if attempt == 2:
                raise
    return out


def reflection_pad1d(input: torch.Tensor, padding):
    logger.debug("GEMS_ENFLAME REFLECTION_PAD1D")
    return _launch_reflection_pad1d(input, padding, out=None)


def reflection_pad1d_out(input: torch.Tensor, padding, out: torch.Tensor):
    logger.debug("GEMS_ENFLAME REFLECTION_PAD1D_OUT")
    return _launch_reflection_pad1d(input, padding, out=out)
